// Inspired by skizzm - snakes
// Link: https://openprocessing.org/sketch/469866

const cellArray = [];
const snakesNum = 2; // Number of snakes in a single cell
const snakeLength = 50;
const turnProbability = 0.125;
const step = 1.5;
const cellSize = 95;
const cellCount = 5;

function setup() {
  createCanvas(720, 720);

  const padding = 30;
  const step = (width - padding * 2) / cellCount;
  const spacing = step - cellSize;
  for (let y = padding; y < height - padding; y += step) {
    for (let x = padding; x < width - padding; x += step) {
      cellArray.push(new Cell(x + step / 2, y + step / 2));
    }
  }
}

function draw() {
  colorMode(HSB, 360, 100, 100, 100);
  noStroke();
  fill(0, 0, 20, 30);
  rect(0, 0, width, height, 30);

  for (const cell of cellArray) {
    cell.update();
    cell.show();
  }
}

class Snake {
  constructor() {
    const x = int(random(-cellSize / 2, cellSize / 2));
    const y = int(random(-cellSize / 2, cellSize / 2));
    const pos = createVector(x, y);
    this.list = [];
    this.list.push(pos);
    this.color = color(random(360), random(10, 70), 100);
    this.dir = createVector(1, 0).rotate(random(PI * 2));
    this.isDead = false;
  }

  update() {
    if (random(1) < turnProbability) {
      this.dir.rotate(PI / 2);
    }
    const head = this.list[0].copy();
    head.add(this.dir.copy().mult(step));
    if (abs(head.x) > cellSize / 2 || abs(head.y) > cellSize / 2) {
      this.isDead = true;
      return;
    }
    this.list.unshift(head);
    if (this.list.length > snakeLength) {
      this.list.pop();
    }
  }

  show(angle) {
    stroke(this.color);
    strokeCap(ROUND);
    noFill();

    const symmetry6 = [
      pos=> pos.copy(),
      pos=> pos.copy().rotate(TWO_PI / 3),
      pos=> pos.copy().rotate((TWO_PI / 3) * 2),
      pos=>createVector(pos.x, -pos.y),
      pos=>createVector(pos.x, -pos.y).rotate(TWO_PI / 3),
      pos=>createVector(pos.x, -pos.y).rotate((TWO_PI / 3) * 2),
    ];

    for (const func of symmetry6) {
      beginShape();
      for (const part of this.list) {
        const { x, y } = func(part).rotate(angle);
        vertex(x, y);
      }
      endShape();
    }
  }
}

class Cell {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.snakes = [];
    this.angle = random(TWO_PI);
  }

  update() {
    while (this.snakes.length < snakesNum) {
      this.snakes.push(new Snake());
    }
    for (const snake of this.snakes) {
      const distance = dist((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), this.x, this.y);
      this.angle += 1 / max(0.1, distance); 
    }
    for (const snake of this.snakes) {
      snake.update();
    }
    this.snakes = this.snakes.filter((snake) => snake.isDead === false);
  }

  show() {
    push();
    translate(this.x, this.y);
    for (const snake of this.snakes) {
      snake.show(this.angle);
    }
    pop();
  }
}


